{#- Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/project-tiles.json
    The projects of ProjectGrid as tiles: cards (picture, featured badge, category and year, title, summary, tags, two links), compact cards in four columns, captions over the pictures, or a bento where the first project takes a big tile.
    Props (p): projects, labels, layout. -#}
{%- set v_projects = (p.projects ?? null) -%}
{%- set v_labels = (p.labels ?? null) -%}
{%- set v_layout = (p.layout ?? 'cards') -%}
{%- set v_over = (ui_t(ui_eq(v_layout, 'overlay')) ? true : ui_eq(v_layout, 'bento')) -%}
{%- set c_13 -%}
  {%- for v_p in ui_l(v_projects) %}
    {%- set v_i = loop.index0 -%}
    {%- set c_12 -%}
      {%- set c_2 -%}
        {{ include('blocks/media-frame.html.twig', {'p': {'alt': ui_get(v_p, ['title']), 'ratio': (ui_t(ui_eq(v_layout, 'compact')) ? '1/1' : (ui_t(v_over) ? '3/4' : '4/3')), 'className': ui_cnv([(ui_t(v_over) ? 'h-full' : '')])}}, with_context = false) }}
        {%- if ui_t(ui_and([ui_get(v_p, ['featured']), not (ui_eq(v_layout, 'compact'))])) %}
          {%- set c_1 -%}
            {{ ui_text(ui_get(v_labels, ['featured'])) }}
          {%- endset -%}
          {{ include('ui/badge/badge.html.twig', {'p': {'Variant': 'default', 'Size': 'default', 'Class': 'absolute left-4 top-4', 'Attrs': ui_attrs(['data-testid', 'featured'])}, 'children': c_1}, with_context = false) }}
        {%- endif %}
      {%- endset -%}
      {{ include('ui/box/box.html.twig', {'p': {'Class': ui_s((ui_t(v_over) ? 'h-full' : 'relative'))}, 'children': c_2}, with_context = false) }}
      {%- set c_11 -%}
        {%- set c_3 -%}
          {{ ui_text(ui_tpl('{0}, {1}', [ui_get(v_p, ['category']), ui_get(v_p, ['year'])])) }}
        {%- endset -%}
        {{ include('ui/text/text.html.twig', {'p': {'Size': 'xs', 'Class': 'text-muted-foreground'}, 'children': c_3}, with_context = false) }}
        {%- set c_4 -%}
          {{ ui_text(ui_get(v_p, ['title'])) }}
        {%- endset -%}
        {{ include('ui/title/title.html.twig', {'p': {'As': ui_i(3), 'Size': ui_s((ui_t(ui_eq(v_layout, 'compact')) ? 'sm' : 'lg')), 'Weight': 'semibold'}, 'children': c_4}, with_context = false) }}
        {%- if ui_t(not (ui_eq(v_layout, 'compact'))) %}
          {%- set c_5 -%}
            {{ ui_text(ui_get(v_p, ['summary'])) }}
          {%- endset -%}
          {{ include('ui/text/text.html.twig', {'p': {'Size': 'sm', 'Class': 'text-muted-foreground'}, 'children': c_5}, with_context = false) }}
        {%- endif %}
        {%- if ui_t(ui_eq(v_layout, 'cards')) %}
          {%- set c_7 -%}
            {%- for v_k in ui_l(ui_get(v_p, ['tags'])) %}
              {%- set c_6 -%}
                {{ ui_text(v_k) }}
              {%- endset -%}
              {{ include('ui/badge/badge.html.twig', {'p': {'Variant': 'secondary', 'Size': 'sm'}, 'children': c_6}, with_context = false) }}
            {%- endfor %}
          {%- endset -%}
          {{ include('ui/group/group.html.twig', {'p': {'Gap': '2', 'Class': 'flex-wrap'}, 'children': c_7}, with_context = false) }}
          {%- set c_10 -%}
            {%- set c_8 -%}
              {{ ui_text(ui_get(v_labels, ['case'])) }}
              {{ include('ui/lucide-icon/lucide-icon.html.twig', {'p': {'Name': 'arrow-right', 'Size': 16}}, with_context = false) }}
            {%- endset -%}
            {{ include('ui/link/link.html.twig', {'p': {'Href': '#/work', 'Variant': 'default', 'Class': 'inline-flex items-center gap-2 text-sm font-medium'}, 'children': c_8}, with_context = false) }}
            {%- set c_9 -%}
              {{ ui_text(ui_get(v_labels, ['view'])) }}
              {{ include('ui/lucide-icon/lucide-icon.html.twig', {'p': {'Name': 'external-link', 'Size': 16}}, with_context = false) }}
            {%- endset -%}
            {{ include('ui/link/link.html.twig', {'p': {'Href': '#/work', 'Variant': 'default', 'Class': 'inline-flex items-center gap-2 text-sm font-medium'}, 'children': c_9}, with_context = false) }}
          {%- endset -%}
          {{ include('ui/group/group.html.twig', {'p': {'Gap': '4', 'Class': 'pt-2'}, 'children': c_10}, with_context = false) }}
        {%- endif %}
      {%- endset -%}
      {{ include('ui/stack/stack.html.twig', {'p': {'Gap': '2', 'Align': 'stretch', 'Class': ui_s((ui_t(v_over) ? 'absolute right-4 bottom-4 left-4 rounded bg-background p-4' : ''))}, 'children': c_11}, with_context = false) }}
    {%- endset -%}
    {{ include('blocks/article-block.html.twig', {'p': {'className': ui_cnv([ui_cnv(['flex flex-col gap-4', (ui_t(v_over) ? 'relative' : 'rounded bg-card inset-ring inset-ring-border p-4'), (ui_t(ui_and([ui_eq(v_layout, 'bento'), ui_eq(v_i, 0)])) ? 'sm:col-span-2 lg:row-span-2' : '')])]), 'testid': 'item'}, 'children': c_12}, with_context = false) }}
  {%- endfor %}
{%- endset -%}
{{ include('ui/box/box.html.twig', {'p': {'Class': ui_s((ui_t(ui_eq(v_layout, 'compact')) ? 'grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4' : 'grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3')), 'Attrs': ui_attrs(['data-testid', 'items'])}, 'children': c_13}, with_context = false) }}
